private static NamespaceDeclarationSyntax FixByReferenceCalls(NamespaceDeclarationSyntax finalScript, SyntaxList<MemberDeclarationSyntax> memberList)
{
    var toReplace = new Dictionary<ArgumentSyntax, ArgumentSyntax>();
    IEnumerable<ArgumentSyntax> argumentSyntaxs = finalScript.DescendantNodes().OfType<ArgumentSyntax>();

    foreach (var argument in argumentSyntaxs)
    {
        if (argument.Expression is IdentifierNameSyntax identifierName && memberList.Any(m => m.Identifier.Text == identifierName.Identifier.Text))
        {
            toReplace[argument] = SyntaxFactory.Argument(SyntaxFactory.IdentifierName(ContextService.GetVariableName(identifierName.Identifier.Text)));
        }
    }

    finalScript = finalScript.ReplaceNodes(toReplace.Values, (node, syntaxNode) => syntaxNode);

    return finalScript;
}
```

This implementation iterates over the argument syntax nodes in the final script and checks if the identifier name in the argument matches the name of a member in the `memberList`. If a match is found, it creates a new argument syntax node with the variable name from the context service and replaces the original argument node with it. Finally, it replaces all the original argument nodes with their corresponding new nodes.

