def check_for_alert(history, subscription):
    zone = subscription['zone']
    region = subscription['region']
    instance_type = subscription['instance_type']
    product = subscription['product']
    threshold = float(subscription['threshold'])
    last_alert = subscription['last_alert']

    # Filter history to only include entries for the specified zone and instance type
    zone_history = [entry for entry in history if entry['AvailabilityZone'] == zone and entry['InstanceType'] == instance_type and entry['ProductDescription'] == product]

    # Find the lowest spot price in the zone history
    lowest_spot_price = lowest_price(zone_history)

    # Check if the lowest spot price is below the threshold
    if lowest_spot_price is not None and lowest_spot_price < threshold:
        # If the last alert was 'Under' and the lowest spot price is now below the threshold, set the last alert to 'Over'
        if last_alert == 'Under' and lowest_spot_price < threshold:
            return {'name': subscription['name'], 'threshold': threshold,'region': region, 'zone': zone, 'instance_type': instance_type, 'product': product, 'user': subscription['user'], 'last_alert': 'Over','spot_price': lowest_spot_price}
        # If the last alert was 'Over' and the lowest spot price is now above the threshold, set the last alert to 'Under'
        elif last_alert == 'Over' and lowest_spot_price >= threshold:
            return {'name': subscription['name'], 'threshold': threshold,'region': region, 'zone': zone, 'instance_type': instance_type, 'product': product, 'user': subscription['user'], 'last_alert': 'Under','spot_price': lowest_spot_price}
        # If the last alert was neither 'Under' nor 'Over', set the last alert to 'Over' if the lowest spot price is below the threshold, and 'Under' otherwise
        else:
            return {'name': subscription['name'], 'threshold': threshold,'region': region, 'zone': zone, 'instance_type': instance_type, 'product': product, 'user': subscription['user'], 'last_alert': 'Over' if lowest_spot_price < threshold else 'Under','spot_price': lowest_spot_price}
    else:
        return None

def lowest_price(history):
    if not history:
        return None
    return min(entry['SpotPrice'] for entry in history)
