                return string.Format("({0},{1})", vector.X, vector.Y);
            }
            if (obj is Vector3)
            {
                var vector = (Vector3) obj;
                return string.Format("({0},{1},{2})", vector.X, vector.Y, vector.Z);
            }
            return obj.ToString();
        }
        return string.Empty;
    }
