class XDREnum(object):
    __slots__ = ['name', 'value']
    members = [
        XDREnum('ENDPOINT_TYPE_KEY', 0),
        XDREnum('ENDPOINT_TYPE_VALUE', 1),
        XDREnum('ENDPOINT_TYPE_STATS', 2)
    ]
    def __init__(self, name, value):
        self.name = name
        self.value = value
    def __int__(self):
        return self.value
    def __str__(self):
        return self.name
    def __repr__(self):
        return self.name
    def __cmp__(x, y):
        return cmp(int(x), int(y))
    def __hash__(self):
        return hash(int(self))
    @classmethod
    def unpack_from(cls, reader):
        value = reader.unpack_int()
        return cls.members[value]
    @classmethod
    def pack_into(cls, packer, value):
        packer.pack_int(value)
