class endpoint(XDRStruct):
    __slots__ = ['type', 'key', 'value','stats']
    def __init__(self, type=None, key=None, value=None, stats=None):
        self.type = type
        self.key = key
        self.value = value
        self.stats = stats
    @classmethod
    def pack_into(self, packer, obj):
        packer.pack_int(obj.type.value)
        if obj.type == XDREnum('ENDPOINT_TYPE_KEY'):
            endpoint_key.pack_into(packer, obj.key)
        elif obj.type == XDREnum('ENDPOINT_TYPE_VALUE'):
            endpoint_value.pack_into(packer, obj.value)
        elif obj.type == XDREnum('ENDPOINT_TYPE_STATS'):
            endpoint_stats.pack_into(packer, obj.stats)
    @classmethod
    def unpack_from(cls, unpacker):
        obj = endpoint()
        obj.type = XDREnum.unpack_from(unpacker)
        if obj.type == XDREnum('ENDPOINT_TYPE_KEY'):
            obj.key = endpoint_key.unpack_from(unpacker)
        elif obj.type == XDREnum('ENDPOINT_TYPE_VALUE'):
            obj.value = endpoint_value.unpack_from(unpacker)
        elif obj.type == XDREnum('ENDPOINT_TYPE_STATS'):
            obj.stats = endpoint_stats.unpack_from(unpacker)
        return obj
    def __eq__(self, other):
        if type(self)!= type(other):
            return False
        if self.type!= other.type:
            return False
        if self.type == XDREnum('ENDPOINT_TYPE_KEY') and (self.key!= other.key or other.key is None):
            return False
        if self.type == XDREnum('ENDPOINT_TYPE_VALUE') and (self.value!= other.value or other.value is None):
            return False
        if self.type == XDREnum('ENDPOINT_TYPE_STATS') and (self.stats!= other.stats or other.stats is None):
            return False
        return True
    def __repr__(self):
        parts = []
        parts.append('endpoint(')
        parts.append('type=')
        parts.append(repr(self.type))
        if self.key is not None:
            parts.append(', key=')
            parts.append(repr(self.key))
        if self.value is not None:
            parts.append(', value=')
            parts.append(repr(self.value))
        if self.stats is not None:
            parts.append(', stats=')
            parts.append(repr(self.stats))
        parts.append(')')
        return ''.join(parts)
