        {
            String key = (String) keys.nextElement();
            String value = props.getProperty(key);
            propsMap.setProperty(key, value);
        }
        return propsMap;
    }
    catch (IOException e)
    {
        throw new RuntimeException("Error loading properties from " + location, e);
