private class MskJointVoComparator implements Comparator
{
    private int direction = 1;
    private boolean caseInsensitive = true;

    public MskJointVoComparator()
    {
        this(SortOrder.ASCENDING);
    }

    public MskJointVoComparator(SortOrder order)
    {
        if (order == SortOrder.DESCENDING)
