    public MskJointVoComparator(SortOrder order, boolean caseInsensitive)
    {
        if (order == SortOrder.DESCENDING)
        {
            direction = -1;
        }
        this.caseInsensitive = caseInsensitive;
    }

    public int compare(Object o1, Object o2)
    {
        int comparison = 0;

        if (o1 instanceof MskJointVo && o2 instanceof MskJointVo)
        {
            MskJointVo joint1 = (MskJointVo)o1;
            MskJointVo joint2 = (MskJointVo)o2;

            if (caseInsensitive)
            {
                comparison = joint1.getName().compareToIgnoreCase(joint2.getName());
            }
            else
            {
                comparison = joint1.getName().compareTo(joint2.getName());
            }

            if (comparison!= 0)
            {
                return direction * comparison;
            }
        }

        return 0;
    }
}
