{
    if ( useShadowBuffer )
    {
        if ( discardWholeBuffer )
        {
            shadowBuffer.Lock( 0, sizeInBytes, BufferLocking.Discard );
        }
        else
        {
            shadowBuffer.Lock( offset, length, BufferLocking.Discard );
        }
