public Drawable FindElement(string Name)
{
    if (this.Name == Name)
        return this;
    var plcs = new System.Collections.Generic.Stack<PlaceBase>();
    if (this is PlaceBase)
        plcs.Push(this as PlaceBase);
    while (plcs.Count!= 0)
    {
        PlaceBase pop = plcs.Pop();
        if (pop.Name == Name)
            return pop;
        for (int i = 0; i < pop.Length; i++)
        {
            if (pop[i] is PlaceBase)
                plcs.Push(pop[i] as PlaceBase);
            else if (pop[i] is Drawable)
                if (((Drawable)pop[i]).FindElement(Name)!= null)
                    return (Drawable)pop[i].FindElement(Name);
        }
    }
    return null;
}
```

This code will recursively search for a child element with a specified name, and return the element if found. If not found, it will return null.

